 function apply(){for(const [name,value] of Object.entries(globalDefaults))document.documentElement.style.setProperty('--site-'+name,state[name]??value);document.dispatchEvent(new Event('site-style-change'));info.style.setProperty('--column-gap',state.gap+'px');info.style.setProperty('--document-width',state.width+'%');columns.forEach((column,index)=>{const c=state.columns[index];const css={'--doc-scale':c.scale,'--doc-x':c.x+'px','--doc-y':c.y+'px','--doc-size':c.size+'px','--doc-family':c.family,'--doc-weight':c.weight,'--doc-leading':c.leading,'--doc-tracking':c.tracking+'em','--doc-word-spacing':c.wordSpacing+'em','--doc-paragraph':c.paragraph+'em','--doc-align':c.align,'--doc-color':c.color};for(const [name,value] of Object.entries(css))column.style.setProperty(name,value);column.classList.toggle('edit-target',selected().includes(index))})}
